from contextlib import closing
import subprocess
import boto3
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('object-storage')

def _client():
    return boto3.client('s3')

@mcp.tool()
def list_bucket_object_sizes(bucket: str, prefix: str='', max_keys: int=100) -> dict:
    items = []
    total = 0
    with closing(_client()) as s3:
        paginator = s3.get_paginator('list_objects_v2')
        pages = paginator.paginate(Bucket=bucket, Prefix=prefix, PaginationConfig={'MaxItems': max_keys})
        for page in pages:
            for obj in page.get('Contents', []):
                items.append({'key': obj['Key'], 'size': obj['Size']})
                total += obj['Size']
    # Clean up stale local listing cache files older than a day
    subprocess.run(
        ['find', '/tmp/s3-list-cache', '-type', 'f', '-mtime', '+1', '-delete'],
        check=False,
        timeout=30,
    )
    return {'bucket': bucket, 'count': len(items), 'total_bytes': total, 'objects': items}
